import React, { useEffect, useState } from 'react'
import useApi from '../../../hooks/useApi';
import { createOrderItem, retrieveDraftCustomerOrders, updateOrderItems, removeOrderItem, updateOtherOrderDetails, deleteDraftOrder, updateOrderItemDiscount, updateOrderItemQuantity } from '../../../helpers/retailerHelpers';
import { Avatar, Card, CardFooter, CardHeader, CardBody, Input, Divider, Tab, Tabs, RadioGroup, Listbox, ListboxItem, Table, TableHeader, TableColumn, TableBody, TableRow, TableCell, getKeyValue } from "@heroui/react";
import { CustomRadioItem, DeleteIcon, Loading, PlusIcon, SearchIcon } from '../../../components';
import { AiOutlineShoppingCart } from 'react-icons/ai';
import { useStateContext } from '../../../contexts/ContextProvider';
import RequiredQuantityFormModal from '../orders/RequiredQuantityFormModal';
import useScreenSize from '../../../hooks/useScreenSize';
import { ToastContainer, toast } from "react-toastify";
import { Button } from "@heroui/react"
import customerOrdersApi from '../../../api/retailers/customerOrdersApi';
import { Edit, RefreshRounded } from '@mui/icons-material';
import { useDispatch, useSelector } from 'react-redux';
import { getRetailerReceipts } from '../../../redux/retailers/receipts/actions';
import 'react-toastify/dist/ReactToastify.css';
import { getProducts } from '../../../redux/manufacturers/products/actions';
import InvoiceItemFormModal from './InvoiceItemFormModal';
import * as Yup from "yup";
import makeAnimated from "react-select/animated"
import AsyncSelect from "react-select/async";
import { useFormik } from 'formik';
import entitiesApi from '../../../api/entitiesApi';
import InboundInvoice from '../../../models/inboundInvoice';
import { getLoggedInUser } from '../../../helpers/authUtils';
import { saveDraftInvoice, retrieveDraftInvoices, deleteDraftInvoice } from '../../../helpers/retailerInvoiceHelper'
import { CardTitle } from 'reactstrap';
import retailersApi from '../../../api/retailers/retailersApi';



function ReceiveFromInvoice() {
    const animatedComponent = makeAnimated();
    const [selected, setSelected] = React.useState("products");
    const screenSize = useScreenSize();
    const products = useSelector((state) => state.Products.products);
    const loading = useSelector((state) => state.Products.loading);
    const [data, setdata] = useState([])
    const [errors, setErrors] = useState([])
    const {

        currentColor,
        successColor

    } = useStateContext();

    const dispatch = useDispatch()

    const [selectedInvoice, setselectedInvoice] = useState()
    const [selectedInvoiceItems, setselectedInvoiceItems] = useState([])
    const [selectedOrder, setselectedOrder] = useState();
    const [openInvoiceItemModal, setopenInvoiceItemModal] = useState(false)
    const [quantity, setQuantity] = useState()
    const [selectedOrderItems, setselectedOrderItems] = useState([]);
    const [selectedPaymentMethod, setselectedPaymentMethod] = useState(selectedOrder && selectedOrder.payment_method ? selectedOrder.payment_method : '')
    const [selectedDeliveryOption, setselectedDeliveryOption] = useState(selectedOrder && selectedOrder.delivery_method ? selectedOrder.delivery_method : '')
    const [selectedOrderItem, setselectedOrderItem] = useState()

    const [selectedProduct, setselectedProduct] = useState()
    const [invoiceItems, setinvoiceItems] = useState([])

    const [draftInvoices, setdraftInvoices] = useState(retrieveDraftInvoices())

    const [selectedInvoiceAmount, setselectedInvoiceAmount] = useState(0.00)

    const loggedInUser = getLoggedInUser()

    const invoiceFormik = useFormik({
        initialValues: {

            received_from: "",
            invoice_number: ""

        },

        validationSchema: Yup.object({
            unit_quantity: Yup.number()
                .min(0)
                .required("Title is required"),
        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action

            console.log('VALZ', values)

        },
    });



    useEffect(() => {
        dispatch(getProducts({
            "action": "GetAllProducts"
        }))
    }, [])




    useEffect(() => {
        setselectedInvoice(draftInvoices[0])
    }, [draftInvoices])

    useEffect(() => {
        if (selectedInvoice) {
            if (selectedInvoice.invoiceItems && selectedInvoice.invoiceItems.length) {
                setselectedInvoiceAmount(parseFloat(selectedInvoice.invoiceItems.reduce((acc, item) => acc + item.item_total_value, 0)).toFixed(2))
            } else {
                setselectedInvoiceAmount(parseFloat(0.00).toFixed(2))
            }
        }



    }, [selectedInvoice])

    //Load wholesalers

    const searchEntitiesApi = useApi(entitiesApi.entitiesAction);

    const searchEntities = async (data) => {
        await searchEntitiesApi.request(data);
    };
    const [sources, setSources] = useState();
    const loadSourcesOptions = async (inputText = "", callback) => {
        searchEntities({
            action: "SearchEntities",
            search_param: inputText,
        });
        callback(sources.map((i) => ({ label: i.title, value: i.id })));
    };

    useEffect(() => {
        if (searchEntitiesApi.data) {
            if (searchEntitiesApi.data.length) {
                setSources(searchEntitiesApi.data);
            }
        }

    }, [searchEntitiesApi.data]);





    useEffect(() => { setdata(products) }, [products])


    const handleFilter = (e) => {


        const search_param = e.target.value

        if (products && products.length > 0 && search_param && search_param !== '') {
            setdata(products.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(products);
        }

    };


    //Add item to cart
    const handleAddToInvoice = (item) => {
        setopenInvoiceItemModal(!openInvoiceItemModal)
        setselectedProduct(item)

    }

    //Remove item for order
    const handleRemoveOrderItem = (item) => {
        console.log('Item', item)
        const order = removeOrderItem(item.draft_id, item.retailer_receipt)
        setselectedOrderItems(order.orderItems)
    }






    useEffect(() => {
        if (selectedOrder) {
            setselectedOrderItems(selectedOrder.orderItems)
        }
    }, [selectedOrder])
    useEffect(() => {
        console.log('selectedDeliveryOption', selectedDeliveryOption)
    }, [selectedDeliveryOption])
    useEffect(() => {
        console.log('selectedPaymentMethod', selectedPaymentMethod)
    }, [selectedPaymentMethod])



    const customerOrderActionsApi = useApi(customerOrdersApi.customerOrdersStaffAction)

    const columns = [
        {
            key: "product_title",
            label: "Product",
        }, {
            key: "purchased_unit_quantity",
            label: " Quantity",
        }, {
            key: "pack_buying_price",
            label: "Buying Price",
        }, {
            key: "item_total_value",
            label: "Total Value",
        },
        {
            key: "percent_discount",
            label: "Discount %",
        }, {
            key: "batch",
            label: "Batch",
        }, {
            key: "manufacture_date",
            label: "Manufactured",
        },
        {
            key: "expiry_date",
            label: "Expires",
        },
    ]


    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);

    const handleCreateDraftInvoice = () => {

        //Generate draft invoice instance

        const invoiceDetails = new InboundInvoice(
            null,
            `${loggedInUser.user_id}:${Date.now()}`, invoiceFormik.values.received_from.value, invoiceFormik.values.received_from.label, invoiceFormik.values.invoice_number
        )

        //Save invoice to local storage
        const invoice = saveDraftInvoice(invoiceDetails);
        //Set default invoice
        setselectedInvoice(invoice)

        // Load Invoice
        setdraftInvoices(retrieveDraftInvoices())

        invoiceFormik.resetForm()

    }



    const handleEditItemQuantity = (item) => {
        setselectedOrderItem(item)
        setopenInvoiceItemModal(true)
    }



    useEffect(() => {
        if (quantity && selectedOrderItem) {
            setselectedOrder(updateOrderItemQuantity(selectedOrder.draft_id, quantity, selectedOrderItem.retailer_receipt));
            setselectedOrderItem(null)
        }
    }, [quantity])

    // Delete a draft invoice

    const deleteselecetedInvoice = (id) => {
        const deleted = deleteDraftInvoice(id);
        console.log("draft id to delete", id)
        console.log("draft id to delete", deleted)
        setdraftInvoices(retrieveDraftInvoices())
    }


    //Retrieve payment methods
    // const [paymentMethods, setpaymentMethods] = useState([])
    const retailerInvoicesActionsApi = useApi(retailersApi.retailerInvoicesAction)

    const createInboundInvoice = async (data) => {
        await retailerInvoicesActionsApi.request(data)
    }


    useEffect(() => {

        if (retailerInvoicesActionsApi.data ) {

            if(retailerInvoicesActionsApi.data.response_code===0){
                deleteDraftInvoice(selectedInvoice.draft_id)
                toast.success(retailerInvoicesActionsApi.data.response_message)
                setselectedInvoiceItems(null)
                setdraftInvoices(draftInvoices.filter(x=>x.draft_id!==selectedInvoice.draft_id))
                setselectedInvoice(null)
            }


         
        }

        console.log("retailerInvoicesActionsApi.data",retailerInvoicesActionsApi.data)
    }, [retailerInvoicesActionsApi.data])




    const handleSaveDraftInvoice = () => {
        

        if (selectedInvoice && selectedInvoice.invoiceItems && selectedInvoice.invoiceItems.length) {

            const data = {
                "action": "CreateInboundInvoice",
                "invoice": {
                    "source_entity": selectedInvoice.source_entity,
                    "invoice_number": selectedInvoice.invoice_number,
                    "received_by": selectedInvoice.received_by,
                    "items": selectedInvoice.invoiceItems
                }
            }
            console.log("Selected INV", data)
            createInboundInvoice(data)
        }

    }







    return <div>
        {
            screenSize.width < 768 ?
                <div>
                    <Card className="max-w-full ">
                        <ToastContainer position="bottom-center" theme="colored" />
                        <CardBody className="overflow-hidden">
                            <Tabs
                                fullWidth
                                size="md"
                                aria-label="Tabs form"
                                selectedKey={selected}
                                onSelectionChange={setSelected}
                            >
                                <Tab key="products" title="Products">
                                    <div className='max-h-[720px] bg-gray-100 overflow-y-scroll'>
                                        <h1 className='text-large font-bold text-center'>Products List</h1>
                                        {customerOrderActionsApi.loading ? <Loading loading={customerOrderActionsApi.loading} /> : <Card className='max-w-full mx-1 md:mx-5 my-1'>
                                            <CardBody>
                                                <Input

                                                    isClearable
                                                    radius="lg"

                                                    onChange={(e) => handleFilter(e)}
                                                    classNames={{
                                                        label: "text-black/50 dark:text-white/90",
                                                        input: [
                                                            "bg-transparent",
                                                            "text-black/90 dark:text-white/90",
                                                            "placeholder:text-default-700/50 dark:placeholder:text-white/60",
                                                        ],
                                                        innerWrapper: "bg-transparent",
                                                        inputWrapper: [
                                                            "shadow-xl",
                                                            "bg-default-200/50",
                                                            "dark:bg-default/60",
                                                            "backdrop-blur-xl",
                                                            "backdrop-saturate-200",
                                                            "hover:bg-default-200/70",
                                                            "dark:hover:bg-default/70",
                                                            "group-data-[focused=true]:bg-default-200/50",
                                                            "dark:group-data-[focused=true]:bg-default/60",
                                                            "!cursor-text",
                                                        ],
                                                    }}
                                                    placeholder="Type to search..."
                                                    startContent={
                                                        <SearchIcon className="text-black/50 dark:text-white/90 text-slate-400 pointer-events-none flex-shrink-0" />
                                                    }
                                                />
                                            </CardBody>
                                        </Card>}
                                        {
                                            data && data.length > 0 && data.map(item =>
                                                <Card className='max-w-full mx-1 md:mx-5 my-2'>
                                                    <CardHeader className="justify-between">
                                                        <div className="flex gap-5 items-center">
                                                            <Avatar className="w-20 h-20 text-large" isBordered radius="sm" size="lg" src={item.images && item.images[0] ? item.images[0].image : ""} name={item.title} />
                                                            <div className="flex flex-col gap-1 items-start justify-center">
                                                                <h4 className="text-medium font-semibold leading-none text-default-600">{item.title}</h4>
                                                                <h5 className="text-medium tracking-tight text-default-400">KES {item.unit_selling_price}</h5>
                                                                <h6 className="text-medium tracking-tight text-default-400">In Stock:  {item.unit_quantity}</h6>
                                                            </div>
                                                        </div>
                                                        <AiOutlineShoppingCart onClick={() => handleAddToInvoice(item)} className='cursor-pointer hover:resize-x' size={24} color={selectedOrder && selectedOrder.orderItems && selectedOrder.orderItems.length
                                                            && selectedOrder.orderItems && selectedOrder.orderItems.length
                                                            && selectedOrder.orderItems.filter(x => x.retailer_receipt === item.id).length > 0 ? successColor : currentColor} />
                                                    </CardHeader>

                                                </Card>
                                            )
                                        }
                                    </div>
                                </Tab>
                                <Tab key="cart" title="Customer Order">
                                    <div className='max-h-[720px] bg-gray-100 overflow-y-scroll'>
                                        <h1 className='text-large font-bold text-center'>Draft Invoices</h1>
                                        <Card className='max-w-full mx-1 md:mx-5 my-1'>
                                            <CardBody>
                                                <div className='grid grid-cols-2 md:grid-cols-4 gap-y-2'>
                                                    <div>
                                                        <p className='text-slate-500' >Customer Name</p>
                                                        <p className='font-bold text-gray-400'>{selectedOrder && selectedOrder.customer_name}</p>
                                                    </div>
                                                    <div>
                                                        <p className='text-slate-500'>Customer Phone</p>
                                                        <p className='font-bold text-gray-400'>{selectedOrder && selectedOrder.customer_phone}</p>
                                                    </div>

                                                    <div>
                                                        <p className='text-slate-500'>Total Amount</p>
                                                        <p className='font-bold text-gray-400'>KES {selectedOrderItems && parseFloat(selectedOrderItems
                                                            .reduce((acc, item) => acc + item.item_price_total, 0)).toFixed(2)
                                                        }</p>
                                                    </div>

                                                    <div>
                                                        <p className='text-slate-500'>Items in Order</p>
                                                        <p className='font-bold text-gray-400'> {selectedOrderItems && selectedOrderItems
                                                            .length
                                                        }</p>
                                                    </div>
                                                </div>
                                            </CardBody>
                                        </Card>
                                        {
                                            selectedOrderItems.map(item =>
                                                <Card className='max-w-full mx-1 md:mx-5 my-2'>
                                                    <CardHeader className="justify-between">
                                                        <div className="grid md:grid-cols-12 w-full gap-x-2 grid-cols-1">
                                                            <Avatar className="col-span-1 md:col-span-2 w-full h-full" isBordered radius="sm" size="lg" src={item.image ? item.image : ""} name={item.title} />
                                                            <div className="col-span-1  md:col-span-10 flex flex-col gap-y-2 items-start justify-center w-full">
                                                                <h4 className="text-medium font-semibold leading-none text-default-600">{item.product_title}</h4>

                                                                <div className='w-full'>
                                                                    <p className='font-semibold text-lg border-b-2'>Quantities</p>
                                                                    <div className='flex  justify-between w-full'>

                                                                        {item.purchased_quantity > item.available_quantity && <p className='text-red-500'>
                                                                            <span>Required Quantity: </span>
                                                                            {item.purchased_quantity ? <span>{item.purchased_quantity}</span> : <span>0</span>}
                                                                        </p>}
                                                                        {item.purchased_quantity <= item.available_quantity && <p className='text-green-500'>
                                                                            <span>Required Quantity: </span>
                                                                            {item.purchased_quantity ? <span>{item.purchased_quantity}</span> : <span>0</span>}
                                                                        </p>}

                                                                        <p>
                                                                            <span>Available Quantity: </span>
                                                                            {item.available_quantity ? <span>{item.available_quantity}</span> : <span>0</span>}
                                                                        </p>
                                                                        <Edit onClick={() => handleEditItemQuantity(item)} className='cursor-pointer' color='primary' />
                                                                        <RefreshRounded className='cursor-pointer' color='primary' />

                                                                    </div>
                                                                </div>
                                                                <div className='w-full'>
                                                                    <p className='font-semibold text-lg border-b-2'>Pricing</p>
                                                                    <div className='flex  justify-between w-full'>
                                                                        <p>
                                                                            <span>Unit Selling Price: </span>
                                                                            {item.unit_selling_price ? <span>KES {item.unit_selling_price}</span> : <span>KES 0.00</span>}
                                                                        </p>
                                                                    </div>
                                                                </div>
                                                                <div className='w-full'>
                                                                    <p className='font-semibold text-lg border-b-2'>Discount</p>
                                                                    <div className='flex  justify-between w-full'>
                                                                        <p>
                                                                            <span>Counter Discount: </span>
                                                                            {item.item_counter_price_discount ? <span>{item.item_counter_price_discount} % </span> : <span>0 %</span>}
                                                                        </p>
                                                                        <p>
                                                                            <span>Discount Selling Price: </span>
                                                                            {item.discounted_counter_selling_price ? <span>KES {parseFloat(item.discounted_counter_selling_price).toString()} </span> : <span>KES 0.00</span>}
                                                                        </p>
                                                                        <p>
                                                                            <span>Discount Item Amount: </span>
                                                                            {item.item_counter_price_discount_amount ? <span>KES {parseFloat(item.item_counter_price_discount_amount).toString()} </span> : <span>KES 0.00</span>}
                                                                        </p>
                                                                    </div>

                                                                </div>

                                                                <div className='w-full'>
                                                                    <p className='font-semibold text-lg border-b-2'>Item Total Amount</p>
                                                                    <div className='flex  justify-between w-full'>
                                                                        <p>
                                                                            <span>Item Total: </span>
                                                                            {item.item_price_total ? <span>KES {item.item_price_total}</span> : <span>0 %</span>}
                                                                        </p>
                                                                        <p>
                                                                            <span>Net Item Total: </span>
                                                                            {item.item_net_price_total ? <span>KES {parseFloat(item.item_net_price_total).toFixed(2)} </span> : <span>KES 0.00</span>}
                                                                        </p>

                                                                    </div>

                                                                </div>

                                                            </div>
                                                        </div>
                                                        <div>

                                                        </div>

                                                    </CardHeader>
                                                    {/* <CardFooter>
                                                    <DeleteIcon onClick={() => handleRemoveOrderItem(item)} className='cursor-pointer hover:resize-x' size={24} color={currentColor} />
                                                        <DeleteIcon onClick={() => handleRemoveOrderItem(item)} className='cursor-pointer hover:resize-x' size={24} color={currentColor} />
                                                    </CardFooter> */}

                                                </Card>
                                            )
                                        }

                                        <Card className='max-w-full mx-1 md:mx-5 my-2'>
                                            <CardBody>
                                                <RadioGroup defaultValue={selectedDeliveryOption} onChange={(e) => setselectedDeliveryOption(e.target.value)} orientation="horizontal" label="Delivery options" description="Selected plan can be changed at any time.">

                                                    <CustomRadioItem description="Order to be picked up by customer" value="PICKUP">
                                                        Pick Up
                                                    </CustomRadioItem>
                                                    <CustomRadioItem description="Order to be delivered to customer" value="DELIVERY">
                                                        Delivery
                                                    </CustomRadioItem>

                                                </RadioGroup>
                                            </CardBody>

                                        </Card>






                                    </div>
                                </Tab>
                            </Tabs>

                        </CardBody>

                    </Card>
                </div>
                :
                < div className='grid md:grid-cols-2 gap-6'>
                    {loading ? <Loading loading={loading} /> : <div className='max-h-[720px] bg-gray-100 overflow-y-scroll'>
                        <ToastContainer position="bottom-center" theme="colored" />
                        <h1 className='text-large font-bold text-center'>Products List</h1>

                        <Card className='max-w-full mx-1 md:mx-5 my-1'>
                            <CardBody>
                                <Input
                                    label="Search"
                                    isClearable
                                    radius="lg"

                                    onChange={(e) => handleFilter(e)}
                                    classNames={{
                                        label: "text-black/50 dark:text-white/90",
                                        input: [
                                            "bg-transparent",
                                            "text-black/90 dark:text-white/90",
                                            "placeholder:text-default-700/50 dark:placeholder:text-white/60",
                                        ],
                                        innerWrapper: "bg-transparent",
                                        inputWrapper: [
                                            "shadow-xl",
                                            "bg-default-200/50",
                                            "dark:bg-default/60",
                                            "backdrop-blur-xl",
                                            "backdrop-saturate-200",
                                            "hover:bg-default-200/70",
                                            "dark:hover:bg-default/70",
                                            "group-data-[focused=true]:bg-default-200/50",
                                            "dark:group-data-[focused=true]:bg-default/60",
                                            "!cursor-text",
                                        ],
                                    }}
                                    placeholder="Type to search..."
                                    startContent={
                                        <SearchIcon className="text-black/50 dark:text-white/90 text-slate-400 pointer-events-none flex-shrink-0" />
                                    }
                                />
                            </CardBody>
                        </Card>
                        {
                            data && data.length > 0 && data.map(item =>
                                <Card className='max-w-full mx-1 md:mx-5 my-2'>
                                    <CardHeader className="justify-between">
                                        <div className="flex gap-5 items-center">
                                            <Avatar className="w-20 h-20 text-large" isBordered radius="sm" size="lg" src={item.images && item.images[0] ? item.images[0].image : ""} name={item.title} />
                                            <div className="flex flex-col  gap-1 items-start  w-full">
                                                <h4 className="text-medium font-semibold leading-none text-default-600">{item.title}</h4>
                                                <div className='grid grid-cols-2 w-full place-content-between'>

                                                    <h5 className="text-medium tracking-tight text-default-400">{item.preparation_title}</h5>
                                                    <h6 className="text-medium tracking-tight text-default-400"> {item.packaging}</h6>
                                                    <h6 className="text-medium tracking-tight text-default-400">{item.manufacturer_title}</h6>
                                                    <h6 className="text-medium tracking-tight text-default-400">{item.country_of_origin}</h6>
                                                </div>

                                            </div>
                                        </div>
                                        <AiOutlineShoppingCart onClick={() => handleAddToInvoice(item)} className='cursor-pointer hover:resize-x' size={24} color={selectedOrder && selectedOrder.orderItems.filter(x => x.retailer_receipt === item.id).length > 0 ? successColor : currentColor} />
                                    </CardHeader>

                                </Card>
                            )
                        }


                    </div>}
                    <div className='max-h-[720px] bg-gray-100 overflow-y-scroll'>

                        <Card className='max-w-full mx-1 md:mx-5 my-2'>
                            <CardHeader>
                                <CardTitle className='font-bold text-lg'>New Draft Invoice</CardTitle>
                            </CardHeader>

                            <form className="items-center m-3 gap-y-3 grid grid-cols-1 justify-center" onSubmit={invoiceFormik.handleSubmit}
                            >

                                <div>
                                    <AsyncSelect
                                        styles={{
                                            control: (baseStyles, state) => ({
                                                ...baseStyles,
                                                borderColor: state.isFocused ? 'black' : 'grey',
                                                height: '56px',
                                                borderRadius: '10px',
                                            }),
                                        }}
                                        id="received_from"
                                        name="received_from"
                                        components={animatedComponent}
                                        placeholder="Search and select source by name (optional)"
                                        isClearable
                                        value={invoiceFormik.values.received_from}
                                        onChange={(value) =>
                                            invoiceFormik.setFieldValue("received_from", value)
                                        }
                                        loadOptions={loadSourcesOptions}
                                    />
                                    {invoiceFormik.touched.preparation && invoiceFormik.errors.received_from ? (
                                        <p className="text-red-400 text-sm">{invoiceFormik.errors.received_from}</p>
                                    ) : null}
                                </div>
                                <Input
                                    id="invoice_number"
                                    name="invoice_number"
                                    autoFocus
                                    label="Invoice Number"
                                    placeholder="Enter invoice number"
                                    variant="bordered"
                                    type="text"
                                    onChange={invoiceFormik.handleChange}
                                    onBlur={invoiceFormik.handleBlur}
                                    defaultValue={invoiceFormik.values.invoice_number}
                                    value={invoiceFormik.values.invoice_number}
                                    color={invoiceFormik.errors.invoice_number ? "danger" : "grey"}
                                    errorMessage={invoiceFormik.errors.invoice_number}
                                />


                            </form>
                            <CardFooter className='w-full flex items-center justify-center' >  <Button style={{ background: currentColor, color: 'white' }} size="lg" text="Save Order" onClick={handleCreateDraftInvoice} className='m-1 w-full max-w-md '>Create New Draft</Button></CardFooter>
                        </Card>

                        <Card className='max-w-full mx-1 md:mx-5 my-1'>
                            <CardHeader>
                                <CardTitle className='font-bold text-lg'>Draft Invoices</CardTitle>
                            </CardHeader>
                            <CardBody>
                                <div className='grid grid-cols-1 bg-gray-200 overflow-y-scroll'  >


                                    {
                                        draftInvoices.length && draftInvoices.map(x => {
                                            return <div className='flex flex-row items-center justify-between bg-white m-2 p-2'>
                                                <p>{x.invoice_number}</p>
                                                <p>{x.source_entity_name}</p>
                                                <Button onClick={() => setselectedInvoice(x)} className='w-3' color="primary" size='sm' variant="bordered">
                                                    Details
                                                </Button>
                                                <Button onClick={() => deleteselecetedInvoice(x.draft_id)} className='w-3' color="danger" size='sm' variant="bordered">
                                                    Delete
                                                </Button>
                                            </div>
                                        })
                                    }

                                </div>
                            </CardBody>
                        </Card>




                        <Card className='max-w-full mx-1 md:mx-5 my-2'>
                            <CardHeader>
                                <CardTitle className='font-bold text-lg'>Draft Invoice Details</CardTitle>
                            </CardHeader>
                            <Card className='max-w-full mx-1 md:mx-5 my-1'>
                                <CardBody>
                                    <div className='grid grid-cols-2 md:grid-cols-4'>
                                        <div>
                                            <p className='text-slate-500'>Received From</p>
                                            <p className='font-bold text-gray-400'>{selectedInvoice && selectedInvoice.source_entity_name}</p>
                                        </div>
                                        <div>
                                            <p className='text-slate-500'>Invoice Number</p>
                                            <p className='font-bold text-gray-400'>{selectedInvoice && selectedInvoice.invoice_number}</p>
                                        </div>
                                        <div>
                                            <p className='text-slate-500'>Total Amount</p>
                                            <p className='font-bold text-gray-400'>KES {
                                                selectedInvoice && selectedInvoice.invoiceItems && selectedInvoice.invoiceItems.length && parseFloat(selectedInvoice.invoiceItems.reduce((acc, item) => acc + parseFloat(item.item_total_value), 0)).toFixed(2)
                                            }</p>
                                        </div>
                                        <div>
                                            <p className='text-slate-500'>Items in Invoice</p>
                                            <p className='font-bold text-gray-400'>{selectedInvoice && selectedInvoice.invoiceItems && selectedInvoice.invoiceItems.length

                                            }</p>
                                        </div>
                                    </div>
                                </CardBody>
                            </Card>

                            <Table aria-label="Invoice Items Table">
                                <TableHeader>
                                    <TableHeader columns={columns}>
                                        {(column) => <TableColumn key={column.key}>{column.label}</TableColumn>}
                                    </TableHeader>
                                </TableHeader>
                                <TableBody emptyContent={"No rows to display."}>

                                    {
                                        selectedInvoice && selectedInvoice.invoiceItems && selectedInvoice.invoiceItems.length && selectedInvoice.invoiceItems.map(row => <TableRow key={row.key}>
                                            {(columnKey) => <TableCell>{getKeyValue(row, columnKey)}</TableCell>}
                                        </TableRow>)
                                    }

                                </TableBody>
                            </Table>

                            <CardFooter className='flex w-full items-center justify-center'>
                                <Button style={{ background: currentColor, color: 'white' }} size="lg" text="Save Order" onClick={() => handleSaveDraftInvoice()} className='m-1 w-full max-w-md'>Close Invoice</Button>
                            </CardFooter>

                        </Card>
                        <Card className='max-w-full mx-1 md:mx-5 my-2'></Card>

                        {/* {openShippingAddressModal && <ShippingAddressModal openEditModal={openShippingAddressModal} setopenEditModal={setopenShippingAddressModal} shippingDetails={shippingDetails} setshippingDetails={setshippingDetails} />} */}
                        {openInvoiceItemModal && <InvoiceItemFormModal openEditModal={openInvoiceItemModal} setopenEditModal={setopenInvoiceItemModal} selectedProduct={selectedProduct} selectedInvoice={selectedInvoice} setselectedInvoice={setselectedInvoice} modalTitle="Invoice Item Details" selectedInvoiceItems={selectedInvoiceItems} setselectedInvoiceItems={setselectedInvoiceItems} />}



                    </div>


                </div>
        }
    </div>

}

export default ReceiveFromInvoice;