import React, { useEffect, useState } from "react";
import * as Yup from "yup";

import { useFormik } from "formik";

import { ToastContainer, toast } from "react-toastify";
import { CustomForm, CustomFormItem, CustomInput, CustomSelectReactSelect } from "../../../components";
import { useStateContext } from "../../../contexts/ContextProvider";
import { Modal } from "antd";
import { Button } from "@heroui/react";

export default function RequiredQuantityFormModal({
  openEditModal,
  setopenEditModal,
  quantity,
  setQuantity,
  unitOfIssue,
  setunitOfIssue,
  modalTitle,
  selectedRetailerReceipt
}) {
  const formik = useFormik({
    initialValues: {
      required_quantity: quantity,
    },

    validationSchema: Yup.object({
      required_quantity: Yup.number().min(1).required().label("Quantity"),
    }),
    onSubmit: (values, { resetForm }) => {
      console.log("VLZ", values);
      //Dispatch action
      setQuantity(values.required_quantity);
      setopenEditModal(false);
      setunitOfIssue(values.unit_of_issue.value);
    },
  });

  useEffect(() => {
    console.log("errors", formik.errors);
  }, []);

  const { currentColor, dangerColor } = useStateContext();

  const handleOk = () => {
    setopenEditModal(false);
  };
  const handleCancel = () => {
    setopenEditModal(false);
  };

  return (
    <div className="w-full">
      <Modal
        maskClosable={false}
        width={420}
        className="w-full text-center uppercase"
        title={modalTitle}
        open={openEditModal}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />
        <CustomForm
                      layout="vertical"
                      handleFinish={formik.handleSubmit}
                      className=" flex flex-col justify-center items-center w-full"
                    >
                      <CustomFormItem
                        touched={formik.touched.required_quantity}
                        error={formik.errors.required_quantity}
                      >

                      <CustomInput
                        id="required_quantity"
                        name="required_quantity"
                        autoFocus
                        label="Quantity"
                        placeholder="Enter required quantity"
                        variant="bordered"
                        type="text"
                        size="large"
                        onChange={formik.handleChange}
                        onBlur={formik.handleBlur}
                        defaultValue={formik.values.required_quantity}
                        value={formik.values.required_quantity}

                        />
                      </CustomFormItem>

                      <CustomFormItem
                        touched={formik.touched.unit_of_issue}
                        error={formik.errors.unit_of_issue}
                      >
                        <CustomSelectReactSelect
                          name="unit_of_issue"
                          id="unit_of_issue"
                          label="Unit of receipt"
                          size="large"
                          onChange={(e) => formik.setFieldValue("unit_of_issue", e)}
                          value={formik.values.unit_of_issue}
                          placeholder="Select unit of issue"
                          options={[
                            { value: "GRAM", label: "GRAM" },
                            { value: "KILOGRAM", label: "KILOGRAM" },
                            { value: "LITRE", label: "LITRE" },
                            { value: "PIECE", label: "PIECE" },
                          ]}
                        />
                      </CustomFormItem>
          <div className="flex flex-row gap-2 justify-end">
            <Button
              onPress={() => {
                setopenEditModal(false);
                formik.resetForm();
              }}
              style={{ background: dangerColor }}
              type="button"
              fullWidth
              color="primary"
              radius="none"
            >
              Cancel
            </Button>
                        <Button
                          style={{ background: currentColor, color: "white" }}
                          type="submit"
                          fullWidth
                          color="primary"
                          radius="none"
                        >
                          Save
                        </Button>
                      </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
